<?php
require dirname(__DIR__).'/app/bootstrap.php';Auth::requireAdmin();$adminTitle='FAQ dan Sponsor';$faqEdit=null;$sponsorEdit=null;if(isset($_GET['faq'])){$s=db()->prepare('SELECT * FROM faqs WHERE id=?');$s->execute([(int)$_GET['faq']]);$faqEdit=$s->fetch();}if(isset($_GET['sponsor'])){$s=db()->prepare('SELECT * FROM sponsors WHERE id=?');$s->execute([(int)$_GET['sponsor']]);$sponsorEdit=$s->fetch();}
if(is_post()){try{verify_csrf();$type=(string)$_POST['type'];if($type==='faq'){$id=(int)($_POST['id']??0);$data=[trim((string)$_POST['question']),trim((string)$_POST['answer']),(int)$_POST['sort_order'],isset($_POST['is_active'])?1:0];if($id){db()->prepare('UPDATE faqs SET question=?,answer=?,sort_order=?,is_active=?,updated_at=NOW() WHERE id=?')->execute(array_merge($data,[$id]));}else{db()->prepare('INSERT INTO faqs(question,answer,sort_order,is_active,created_at,updated_at) VALUES(?,?,?,?,NOW(),NOW())')->execute($data);}audit('SAVE_FAQ','faqs',$id?:null);}elseif($type==='sponsor'){$id=(int)($_POST['id']??0);$logo=save_upload('logo','sponsors');$data=[trim((string)$_POST['name']),trim((string)$_POST['website_url']),(int)$_POST['sort_order'],isset($_POST['is_active'])?1:0];if($id){$sql='UPDATE sponsors SET name=?,website_url=?,sort_order=?,is_active=?'.($logo?',logo=?':'').',updated_at=NOW() WHERE id=?';$p=$data;if($logo)$p[]=$logo;$p[]=$id;db()->prepare($sql)->execute($p);}else{db()->prepare('INSERT INTO sponsors(name,logo,website_url,sort_order,is_active,created_at,updated_at) VALUES(?,?,?,?,?,NOW(),NOW())')->execute([$data[0],$logo,$data[1],$data[2],$data[3]]);}audit('SAVE_SPONSOR','sponsors',$id?:null);}flash('success','Data berhasil disimpan.');redirect('admin/faqs.php');}catch(Throwable $e){flash('danger',$e->getMessage());redirect('admin/faqs.php');}}
$faqs=db()->query('SELECT * FROM faqs ORDER BY sort_order,id')->fetchAll();$sponsors=db()->query('SELECT * FROM sponsors ORDER BY sort_order,id')->fetchAll();require __DIR__.'/partials/header.php';
?>
<div class="row g-4"><div class="col-xl-6"><div class="admin-card p-4 mb-4"><h5><?= $faqEdit?'Edit':'Tambah' ?> FAQ</h5><form method="post" class="row g-3 mt-1"><?= csrf_field() ?><input type="hidden" name="type" value="faq"><input type="hidden" name="id" value="<?= (int)($faqEdit['id']??0) ?>"><div class="col-12"><label class="form-label">Pertanyaan</label><input class="form-control" name="question" required value="<?= e($faqEdit['question']??'') ?>"></div><div class="col-12"><label class="form-label">Jawaban</label><textarea class="form-control" rows="4" name="answer" required><?= e($faqEdit['answer']??'') ?></textarea></div><div class="col-4"><label class="form-label">Urutan</label><input class="form-control" type="number" name="sort_order" value="<?= e($faqEdit['sort_order']??0) ?>"></div><div class="col-8 d-flex align-items-end pb-2"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_active" <?= !isset($faqEdit['is_active'])||$faqEdit['is_active']?'checked':'' ?>><label class="form-check-label">Aktif</label></div></div><div class="col-12"><button class="btn btn-admin">Simpan FAQ</button></div></form></div><div class="admin-card overflow-hidden"><div class="list-group list-group-flush"><?php foreach($faqs as $f):?><a href="?faq=<?= (int)$f['id'] ?>" class="list-group-item list-group-item-action py-3"><strong><?= e($f['question']) ?></strong><small class="d-block text-secondary text-truncate"><?= e($f['answer']) ?></small></a><?php endforeach;?></div></div></div>
<div class="col-xl-6"><div class="admin-card p-4 mb-4"><h5><?= $sponsorEdit?'Edit':'Tambah' ?> Sponsor/Mitra</h5><form method="post" enctype="multipart/form-data" class="row g-3 mt-1"><?= csrf_field() ?><input type="hidden" name="type" value="sponsor"><input type="hidden" name="id" value="<?= (int)($sponsorEdit['id']??0) ?>"><div class="col-12"><label class="form-label">Nama</label><input class="form-control" name="name" required value="<?= e($sponsorEdit['name']??'') ?>"></div><div class="col-12"><label class="form-label">Logo</label><input class="form-control" type="file" name="logo" accept="image/*"></div><div class="col-12"><label class="form-label">Website</label><input class="form-control" type="url" name="website_url" value="<?= e($sponsorEdit['website_url']??'') ?>"></div><div class="col-4"><label class="form-label">Urutan</label><input class="form-control" type="number" name="sort_order" value="<?= e($sponsorEdit['sort_order']??0) ?>"></div><div class="col-8 d-flex align-items-end pb-2"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_active" <?= !isset($sponsorEdit['is_active'])||$sponsorEdit['is_active']?'checked':'' ?>><label class="form-check-label">Aktif</label></div></div><div class="col-12"><button class="btn btn-admin">Simpan Sponsor</button></div></form></div><div class="admin-card overflow-hidden"><div class="list-group list-group-flush"><?php foreach($sponsors as $s):?><a href="?sponsor=<?= (int)$s['id'] ?>" class="list-group-item list-group-item-action d-flex align-items-center gap-3"><img src="<?= upload_url($s['logo'],'images/logo.svg') ?>" width="60" height="44" class="object-fit-contain"><div><strong><?= e($s['name']) ?></strong><small class="d-block text-secondary"><?= e($s['website_url']) ?></small></div></a><?php endforeach;?></div></div></div></div>
